import { useState, useEffect, useRef } from 'react';
import Chart from 'chart.js/auto';

function Frame() {
  return (
    <div
      style={{
        backgroundColor: '#6ab4ff',
        width: '168px',
        height: '50px',
        borderRadius: '10px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '10px 37px',
        boxSizing: 'border-box',
      }}
    >
      <p
        style={{
          margin: 0,
          fontFamily: "'Inria Sans', 'Noto Sans KR', sans-serif",
          fontSize: '24px',
          lineHeight: 'normal',
          color: '#000',
        }}
      >
        스캔 시작
      </p>
    </div>
  );
}

function Frame1({ target, setTarget, onSubmit, loading }) {
  return (
    <div
      style={{
        width: '100%',
        height: '66px',
        backgroundColor: '#fff',
        position: 'relative',
        boxSizing: 'border-box',
      }}
    >
      <div
        aria-hidden="true"
        style={{
          position: 'absolute',
          inset: 0,
          border: '1px solid #505050',
          boxSizing: 'border-box',
          pointerEvents: 'none',
        }}
      />
      <form
        onSubmit={onSubmit}
        style={{
          position: 'absolute',
          inset: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '8px 18px',
          boxSizing: 'border-box',
        }}
      >
        <input
          value={target}
          onChange={e => setTarget(e.target.value)}
          placeholder="예: scanme.nmap.org"
          style={{
            width: '100%',
            height: '50px',
            borderRadius: '8px',
            border: '1px solid #d1d5db',
            padding: '0 14px',
            fontSize: '16px',
            fontFamily: "'Noto Sans KR', sans-serif",
            outline: 'none',
            boxSizing: 'border-box',
          }}
        />
        <button
          type="submit"
          disabled={loading}
          style={{
            marginLeft: '16px',
            background: 'transparent',
            border: 'none',
            padding: 0,
            cursor: loading ? 'default' : 'pointer',
          }}
        >
          <Frame />
        </button>
      </form>
    </div>
  );
}

export default function Frame2() {
  const [target, setTarget] = useState('');
  const [scanData, setScanData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const assetChartRef = useRef(null);
  const vulnChartRef  = useRef(null);
  const riskChartRef  = useRef(null);


  const handleScan = async event => {
    event.preventDefault();
    setError('');
    setScanData(null);
    if (!target.trim()) {
      setError('IP 주소 또는 도메인을 입력하세요.');
      return;
    }

    setLoading(true);
    try {
      const response = await fetch('http://127.0.0.1:8000/scan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ target })
      });
      const data = await response.json();
      setScanData(data);
      //const response = await fetch(`/api/scan?target=${encodeURIComponent(target)}`);
      //if (!response.ok) {
      //  throw new Error(`HTTP ${response.status}`);
      //}
      //const data = await response.json();
      //setScanData(data);
    } catch (err) {
      console.error(err);
      setError('⚠ 스캔 중 오류가 발생했습니다.');
    } finally {
      setLoading(false);
    }
  };

 useEffect(() => {
  if (!scanData) return;

  // 1) 자산 차트 데이터
  new Chart(assetChartRef.current, {
    type: 'bar',
    data: {
      labels: ['Assets'],
      datasets: [{
        label: '개수',
        data: [scanData.assets.length],
        backgroundColor: ['#35607b']
      }]
    },
    options: { indexAxis: 'y' }
  });

  // 2) 취약점 심각도 데이터 세기
  const counts = { low:0, medium:0, high:0 };
  scanData.vulnerabilities.forEach(v => {
    if (counts[v.severity] !== undefined) counts[v.severity]++;
  });
  new Chart(vulnChartRef.current, {
    type: 'pie',
    data: {
      labels: ['low','medium','high'],
      datasets: [{
        data: [counts.low, counts.medium, counts.high],
        backgroundColor: ['green','orange','red']
      }]
    }
  });

  // 3) 위험도 분포 세기
  const rcounts = { safe:0, warning:0, danger:0 };
  scanData.risks.forEach(r => {
    if (rcounts[r.level] !== undefined) rcounts[r.level]++;
  });
  new Chart(riskChartRef.current, {
    type: 'doughnut',
    data: {
      labels: ['safe','warning','danger'],
      datasets: [{
        data: [rcounts.safe, rcounts.warning, rcounts.danger],
        backgroundColor: ['skyblue','gold','crimson']
      }]
    }
  });

 }, [scanData]);



  return (
    <div
      style={{
        // 1) 화면 전체가 꽉 차지 않도록 최대 너비 제한
        maxWidth: '600px',
        margin: '20px auto',      // 상하 20px 여백, 좌우 중앙정렬
        padding: '20px',
        boxSizing: 'border-box',
      }}
    >
      {/* 검색 영역 */}
      <div
        style={{
          // 2) 검색 박스 크기 제한
          maxWidth: '400px',
          marginBottom: '16px',
        }}
      >
        <h2>IP 주소 또는 도메인 입력:</h2>
        <Frame1
          target={target}
          setTarget={setTarget}
          onSubmit={handleScan}
          loading={loading}
        />
        {error && <p style={{ color: 'red', marginTop: '8px' }}>{error}</p>}
      </div>

      {/* 결과 영역 */}
      <div
        style={{
          // 3) 결과 박스 크기 제한
          maxWidth: '560px',
          height: 'auto',         // 내용에 맞게 늘어나도록
          background: '#fff',
          border: '1px solid #676767',
          padding: '18px',
          boxSizing: 'border-box',
        }}
      >
        <h2 style={{ marginTop: 0 }}>결과 확인:</h2>
        {scanData ? (
          <div style={{ overflowX: 'auto' }}>
            {/* 호스트 정보 */}
            <div style={{ marginBottom: '12px', fontSize: '14px' }}>
              <strong>스캔 대상:</strong> {scanData.target} ({scanData.ip})<br />
              <strong>열린 포트 개수:</strong> {scanData.ports.length}
            </div>

            {/* 포트 테이블 */}
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
              <thead>
                <tr style={{ background: '#f3f4f6' }}>
                  {['Port', 'OS', 'Service', 'Version'].map(h => (
                    <th
                      key={h}
                      style={{ border: '1px solid #ddd', padding: '6px 8px', textAlign: 'left' }}
                    >
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {scanData.ports.map((p, i) => (
                  <tr key={i}>
                    <td style={{ border: '1px solid #ddd', padding: '6px 8px' }}>{p.port}</td>
                    <td style={{ border: '1px solid #ddd', padding: '6px 8px' }}>{p.os}</td>
                    <td style={{ border: '1px solid #ddd', padding: '6px 8px' }}>{p.service}</td>
                    <td style={{ border: '1px solid #ddd', padding: '6px 8px' }}>{p.version}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* 차트 */}
            <div style={{ marginTop: '24px' }}>
              <h3 style={{ fontSize: '16px', marginBottom: '8px' }}>자산(Assets) 개수</h3>
              <canvas ref={assetChartRef} style={{ width: '100%', height: '150px' }} />

              <h3 style={{ fontSize: '16px', margin: '16px 0 8px' }}>취약점(Vulnerabilities) 심각도</h3>
              <canvas ref={vulnChartRef} style={{ width: '100%', height: '150px' }} />

              <h3 style={{ fontSize: '16px', margin: '16px 0 8px' }}>위험도(Risks) 분포</h3>
              <canvas ref={riskChartRef} style={{ width: '100%', height: '150px' }} />
            </div>
          </div>
        ) : (
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#6b7280',
              fontSize: '14px',
              height: '120px',
            }}
          >
            스캔 결과가 여기에 표시됩니다.
          </div>
        )}
      </div>
    </div>
  );
}
